return items.map(item => {
  const data = item.json;

  const rules = {
    instagram: {
      output_type: 'card_news',

      default_card_count: {
        min: 3,
        max: 5
      },

      card_count_adjustable: true,

      first_card_role: 'cover',
      middle_card_role: 'body',
      last_card_role: 'closing',

      black_card_default: true,

      image_auto_insert: false,
      image_user_selectable: true,

      core_text_required: true,

      one_message_per_card: true,

      evidence_required: true
    },

    threads: {
      output_type: 'short_post',
      concise: true,
      paragraph_style: 'short',
      evidence_required: true
    },

    blog: {
      output_type: 'long_form',
      use_sections: true,
      intro_required: true,
      conclusion_required: true,
      evidence_required: true
    }
  };

  const selectedRule = rules[data.platform];

  if (!selectedRule) {
    throw new Error(
      `지원하지 않는 플랫폼입니다: ${data.platform}`
    );
  }

  return {
    json: {
      ...data,
      platform_rules: selectedRule
    }
  };
});

